CREATE TABLE live_strategy_capital_account(strategy_instance_id varchar(120) primary key,initial_capital numeric(18,2) not null,realized_net_pnl numeric(18,2) not null default 0,reserved_amount numeric(18,2) not null default 0,updated_at timestamp not null default current_timestamp);
CREATE TABLE live_strategy_capital_ledger(capital_event_id bigserial primary key,strategy_instance_id varchar(120) not null,event_type varchar(32) not null,amount numeric(18,2) not null,balance_after numeric(18,2) not null,related_intent_id uuid,related_order_request_id uuid,related_fill_id uuid,occurred_at timestamp not null,created_at timestamp not null default current_timestamp,reason varchar(256) not null,audit_detail jsonb not null default '{}'::jsonb);
CREATE TABLE live_order_request(order_request_id uuid primary key,idempotency_key char(64) not null unique,strategy_instance_id varchar(120) not null,source_intent_id uuid not null,source_decision_id uuid not null,execution_stock_code varchar(32) not null,side varchar(8) not null,requested_notional numeric(18,2) not null,requested_quantity integer,reference_price numeric(18,2),order_type varchar(32) not null,execution_target_time timestamp not null,strategy_capital_before numeric(18,2) not null,reserved_capital numeric(18,2) not null,safety_status varchar(64) not null,status varchar(32) not null,reason varchar(256) not null,detail jsonb not null default '{}'::jsonb,created_at timestamp not null default current_timestamp);
CREATE TABLE live_order_safety_audit(audit_id bigserial primary key,event_type varchar(64) not null,strategy_instance_id varchar(120) not null,source_intent_id uuid,event_time timestamp not null,reason varchar(256) not null,detail jsonb not null default '{}'::jsonb,created_at timestamp not null default current_timestamp);
